#!/usr/bin/env python3
"""Install the AI review foundation update from the project root."""
import importlib.util
import json
import os
from pathlib import Path
import tempfile
from datetime import datetime, timezone
import zipfile

FILES = {'auditor/review/__init__.py': '"""Validated AI-review storage, separate from scanner verdicts and report prose."""\n', 'auditor/review/store.py': '"""Local-only AI review schema, evidence validation and atomic storage.\n\nNo AI calls, target requests, HTML rendering or automatic verification occurs.\nValidated references establish provenance links, not the truth of model prose.\n"""\nimport argparse\nfrom copy import deepcopy\nfrom datetime import datetime, timezone\nfrom functools import lru_cache\nimport hashlib\nimport json\nfrom pathlib import Path\n\nfrom jsonschema import Draft202012Validator, FormatChecker\nfrom auditor.reporting.validation import load_report_data, unique_object, reject_constant\nfrom auditor.resume_engine import lock_run\n\nMAX_BYTES = 4 * 1024 * 1024\nREVIEW_PATH = \'results/ai_review.json\'\nSUPPORTED = {\'CHK05\': \'review_error_context\', \'CHK07\': \'review_reflection_context\',\n             \'CHK08\': \'review_input_handling\'}\n\n\nclass ReviewError(ValueError):\n    """Safe, fixed-message validation failure; no rejected content is echoed."""\n\n\n@lru_cache(maxsize=1)\ndef schema():\n    path = Path(__file__).parents[1] / \'reporting/schemas/ai_review.json\'\n    value = json.loads(path.read_text(encoding=\'utf-8\'))\n    Draft202012Validator.check_schema(value)\n    return value\n\n\ndef _check(value, definition=None):\n    spec = schema() if definition is None else schema()[\'$defs\'][definition]\n    if not Draft202012Validator(spec, format_checker=FormatChecker()).is_valid(value):\n        raise ReviewError(\'AI review schema validation failed.\')\n\n\ndef _read(path):\n    try:\n        with path.open(\'rb\') as handle:\n            raw = handle.read(MAX_BYTES + 1)\n        if len(raw) > MAX_BYTES:\n            raise ReviewError(\'AI review file exceeds the size limit.\')\n        return json.loads(raw.decode(\'utf-8\'), object_pairs_hook=unique_object,\n                          parse_constant=reject_constant)\n    except (OSError, ValueError, UnicodeError, RecursionError):\n        raise ReviewError(\'AI review file is unreadable or invalid.\') from None\n\n\ndef _digest(value):\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\',\', \':\'),\n                                   ensure_ascii=False, allow_nan=False).encode()).hexdigest()\n\n\ndef _index(records):\n    result = {}\n    for record in records:\n        identifier = record[\'id\']\n        if identifier in result:\n            raise ReviewError(\'Duplicate source record ID.\')\n        result[identifier] = record\n    return result\n\n\ndef _source(run):\n    try:\n        data = load_report_data(run)\n        tests = _index(data[\'tests\'])\n        evidence = _index(data[\'evidence\'])\n        if {p.stem for p in (Path(run) / \'evidence\').glob(\'*.json\')} != set(evidence):\n            raise ReviewError(\'Source evidence filename does not match its ID.\')\n        for item in evidence.values():\n            info = item[\'content_hash\']\n            actual = _digest({k: v for k, v in item.items() if k != \'content_hash\'})\n            if (info[\'algorithm\'] != \'sha256\' or info[\'value\'] != actual or\n                    info[\'scope\'] != \'Canonical JSON excluding content_hash\'):\n                raise ReviewError(\'Source evidence hash validation failed.\')\n        # Snapshot parsed source data, including all evidence. JSON formatting is irrelevant.\n        source_hash = _digest({k: data[k] for k in (\'scan\', \'tests\', \'findings\', \'evidence\')})\n        eligible = {key: t for key, t in tests.items() if t[\'rule_id\'] in SUPPORTED\n                    and t[\'status\'] != \'Not Tested\' and t[\'evidence_refs\']}\n        for test in eligible.values():\n            _validate_refs(test, test[\'evidence_refs\'], evidence)\n        return data[\'scan\'][\'id\'], source_hash, eligible, evidence\n    except ReviewError:\n        raise\n    except (OSError, ValueError, TypeError, KeyError, RecursionError):\n        raise ReviewError(\'Source result validation failed.\') from None\n\n\ndef _validate_refs(test, refs, evidence):\n    for ref in refs:\n        if ref not in test[\'evidence_refs\'] or ref not in evidence:\n            raise ReviewError(\'Evidence reference does not belong to the reviewed test.\')\n        item = evidence[ref]\n        owners = item.get(\'test_ids\', [])\n        if not isinstance(owners, list) or any(not isinstance(x, str) for x in owners):\n            raise ReviewError(\'Source evidence ownership is invalid.\')\n        owners = owners + ([item[\'test_id\']] if item.get(\'test_id\') else [])\n        if test[\'id\'] not in owners:\n            raise ReviewError(\'Source evidence backlink does not match the reviewed test.\')\n\n\ndef _status(eligible, reviews):\n    if not eligible:\n        return \'not_applicable\'\n    if not reviews:\n        return \'pending\'\n    return \'complete\' if len(reviews) == len(eligible) else \'partial\'\n\n\ndef _validate(state, source):\n    _check(state)\n    run_id, fingerprint, eligible, evidence = source\n    if state[\'run_id\'] != run_id or state[\'source_hash\'] != fingerprint:\n        raise ReviewError(\'AI review source is stale or belongs to another run.\')\n    seen = set()\n    for item in state[\'reviews\']:\n        test = eligible.get(item[\'test_id\'])\n        if test is None:\n            raise ReviewError(\'Reviewed test is missing, unsupported or not eligible.\')\n        if item[\'test_id\'] in seen:\n            raise ReviewError(\'Duplicate review for the same test.\')\n        seen.add(item[\'test_id\'])\n        if item[\'rule_id\'] != test[\'rule_id\'] or item[\'scanner_status\'] != test[\'status\']:\n            raise ReviewError(\'Review metadata differs from scanner results.\')\n        _validate_refs(test, item[\'payload\'][\'evidence_refs\'], evidence)\n        if item[\'payload\'][\'suggested_verification\'] not in (\'none\', SUPPORTED[test[\'rule_id\']]):\n            raise ReviewError(\'Suggested verification does not match the reviewed rule.\')\n    if state[\'status\'] != _status(eligible, state[\'reviews\']):\n        raise ReviewError(\'AI review completion status is inconsistent.\')\n    return state\n\n\ndef _destination(run):\n    run = Path(run).resolve()\n    if not run.is_dir() or not (run / \'results\').is_dir():\n        raise ReviewError(\'Run and results directories are required.\')\n    for relative in (REVIEW_PATH, \'results\', \'.resume.lock\'):\n        if (run / relative).is_symlink():\n            raise ReviewError(\'Symlink review destinations are not supported.\')\n    return run, run / REVIEW_PATH\n\n\ndef _write(path, state):\n    # Validate/serialize before atomic replacement, avoiding partial or oversized writes.\n    raw = json.dumps(state, indent=2, ensure_ascii=False, allow_nan=False).encode(\'utf-8\')\n    if len(raw) > MAX_BYTES:\n        raise ReviewError(\'AI review store exceeds the size limit.\')\n    from auditor.scanner import save_json\n    save_json(path, state)\n\n\ndef initialize(run):\n    """Create an empty pending store. Existing valid reviews are preserved."""\n    run, path = _destination(run)\n    with lock_run(run):\n        source = _source(run)\n        if path.exists():\n            return deepcopy(_validate(_read(path), source))\n        state = {\'schema_version\': 1, \'run_id\': source[0], \'source_hash\': source[1],\n                 \'status\': _status(source[2], []), \'reviews\': []}\n        _validate(state, source)\n        _write(path, state)\n        return deepcopy(state)\n\n\ndef load_reviews(run):\n    """Validate persisted review structure, source snapshot and evidence links."""\n    run, path = _destination(run)\n    with lock_run(run):\n        return deepcopy(_validate(_read(path), _source(run)))\n\n\ndef save_review(run, test_id, payload, *, provider, model):\n    """Future integration boundary: caller binds test/provider, model supplies payload only.\n\n    Upserts one review under the run lock. Failed validation leaves files unchanged.\n    Provider/model are supplied by the host; metadata is not proof of an actual AI call.\n    """\n    _check(payload, \'payload\')\n    run, path = _destination(run)\n    with lock_run(run):\n        source = _source(run)\n        if path.exists():\n            state = _validate(_read(path), source)\n        else:\n            state = {\'schema_version\': 1, \'run_id\': source[0], \'source_hash\': source[1],\n                     \'status\': _status(source[2], []), \'reviews\': []}\n        test = source[2].get(test_id)\n        if test is None:\n            raise ReviewError(\'Reviewed test is missing, unsupported or not eligible.\')\n        entry = {\'test_id\': test_id, \'rule_id\': test[\'rule_id\'],\n                 \'scanner_status\': test[\'status\'], \'provider\': provider, \'model\': model,\n                 \'created_at\': datetime.now(timezone.utc).isoformat(),\n                 \'review_required\': True, \'payload\': deepcopy(payload)}\n        state[\'reviews\'] = [r for r in state[\'reviews\'] if r[\'test_id\'] != test_id] + [entry]\n        state[\'status\'] = _status(source[2], state[\'reviews\'])\n        _validate(state, source)\n        _write(path, state)\n        return deepcopy(state)\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\'Initialize or validate local AI-review storage; no network requests.\')\n    parser.add_argument(\'--run\', required=True, type=Path)\n    action = parser.add_mutually_exclusive_group(required=True)\n    action.add_argument(\'--init\', action=\'store_true\', help=\'Create an empty store; preserve existing valid reviews\')\n    action.add_argument(\'--validate\', action=\'store_true\', help=\'Validate an existing review store\')\n    args = parser.parse_args()\n    try:\n        state = initialize(args.run) if args.init else load_reviews(args.run)\n    except (ReviewError, OSError, ValueError):\n        # Do not print raw provider content, source values or filesystem exception details.\n        parser.exit(1, \'AI review validation: FAIL. Check source integrity, review schema and source version.\\n\')\n    print(\'AI review validation: PASS\')\n    print(\'Review status:\', state[\'status\'])\n    print(\'Stored reviews:\', len(state[\'reviews\']))\n    print(\'Store:\', str(args.run / REVIEW_PATH))\n    print(\'No AI generation, target requests or follow-up tests were performed.\')\n\n\nif __name__ == \'__main__\':\n    main()\n', 'auditor/reporting/schemas/ai_review.json': '{\n  "$schema": "https://json-schema.org/draft/2020-12/schema",\n  "type": "object",\n  "additionalProperties": false,\n  "required": [\n    "schema_version",\n    "run_id",\n    "source_hash",\n    "status",\n    "reviews"\n  ],\n  "properties": {\n    "schema_version": {\n      "const": 1\n    },\n    "run_id": {\n      "type": "string",\n      "minLength": 1,\n      "maxLength": 200,\n      "pattern": "^[A-Za-z0-9_.:-]+$"\n    },\n    "source_hash": {\n      "type": "string",\n      "pattern": "^[0-9a-f]{64}$"\n    },\n    "status": {\n      "enum": [\n        "pending",\n        "partial",\n        "complete",\n        "not_applicable"\n      ]\n    },\n    "reviews": {\n      "type": "array",\n      "maxItems": 1000,\n      "items": {\n        "$ref": "#/$defs/review"\n      }\n    }\n  },\n  "$defs": {\n    "payload": {\n      "type": "object",\n      "additionalProperties": false,\n      "required": [\n        "assessment",\n        "explanation",\n        "uncertainty",\n        "evidence_refs",\n        "suggested_verification"\n      ],\n      "properties": {\n        "assessment": {\n          "enum": [\n            "consistent_with_observation",\n            "possible_false_positive",\n            "insufficient_context",\n            "needs_human_review"\n          ]\n        },\n        "explanation": {\n          "type": "string",\n          "minLength": 1,\n          "maxLength": 2200,\n          "pattern": "^[^\\\\u0980-\\\\u09ff]*$"\n        },\n        "uncertainty": {\n          "type": "string",\n          "minLength": 1,\n          "maxLength": 2200,\n          "pattern": "^[^\\\\u0980-\\\\u09ff]*$"\n        },\n        "evidence_refs": {\n          "type": "array",\n          "minItems": 1,\n          "maxItems": 20,\n          "uniqueItems": true,\n          "items": {\n            "type": "string",\n            "minLength": 1,\n            "maxLength": 200,\n            "pattern": "^[A-Za-z0-9_.:-]+$"\n          }\n        },\n        "suggested_verification": {\n          "enum": [\n            "none",\n            "review_error_context",\n            "review_reflection_context",\n            "review_input_handling"\n          ]\n        }\n      }\n    },\n    "review": {\n      "type": "object",\n      "additionalProperties": false,\n      "required": [\n        "test_id",\n        "rule_id",\n        "scanner_status",\n        "provider",\n        "model",\n        "created_at",\n        "review_required",\n        "payload"\n      ],\n      "properties": {\n        "test_id": {\n          "type": "string",\n          "minLength": 1,\n          "maxLength": 200,\n          "pattern": "^[A-Za-z0-9_.:-]+$"\n        },\n        "rule_id": {\n          "enum": [\n            "CHK05",\n            "CHK07",\n            "CHK08"\n          ]\n        },\n        "scanner_status": {\n          "enum": [\n            "Confirmed",\n            "Potential",\n            "Inconclusive",\n            "No Issue Observed"\n          ]\n        },\n        "provider": {\n          "enum": [\n            "ollama",\n            "openai-compatible"\n          ]\n        },\n        "model": {\n          "type": "string",\n          "minLength": 1,\n          "maxLength": 200,\n          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:/-]*$"\n        },\n        "created_at": {\n          "type": "string",\n          "format": "date-time"\n        },\n        "review_required": {\n          "const": true\n        },\n        "payload": {\n          "$ref": "#/$defs/payload"\n        }\n      }\n    }\n  }\n}\n', 'tests/test_ai_review_store.py': 'from copy import deepcopy\nimport json\nfrom pathlib import Path\nimport tempfile\nimport unittest\nfrom unittest.mock import patch\n\nfrom auditor.review.store import (initialize, load_reviews, save_review, ReviewError,\n                                  REVIEW_PATH, _digest)\nfrom auditor.resume_engine import lock_run\n\nPAYLOAD = {\'assessment\':\'needs_human_review\', \'explanation\':\'A server error alone does not demonstrate injection.\',\n \'uncertainty\':\'Only one malformed value was tested.\', \'evidence_refs\':[\'ev-one\'],\n \'suggested_verification\':\'review_input_handling\'}\n\nclass ReviewStoreTests(unittest.TestCase):\n def setUp(self):\n  self.temp=tempfile.TemporaryDirectory();self.addCleanup(self.temp.cleanup)\n  self.run=Path(self.temp.name)/\'scan-demo\';(self.run/\'results\').mkdir(parents=True)\n  (self.run/\'evidence\').mkdir()\n  self.scan={\'id\':\'scan-demo\',\'tool_version\':\'test\',\'status\':\'finished\',\'request_count\':0,\n             \'started_at\':\'2026-10-21\',\'ended_at\':None}\n  self.test={\'id\':\'test-one\',\'rule_id\':\'CHK08\',\'rule_version\':\'0.1.0\',\'category\':\'A10:2025\',\n   \'title\':\'Input handling\',\'status\':\'Potential\',\'reason\':\'Server error\',\'steps\':[],\n   \'expected\':\'Handled input\',\'limitations\':[],\'evidence_refs\':[\'ev-one\'],\'request_count\':0}\n  self.tests=[self.test];self.save(\'scan.json\',self.scan);self.save(\'results/tests.json\',self.tests)\n  self.save(\'results/findings.json\',[])\n  self.evidence(\'ev-one\',[\'test-one\'])\n def save(self,name,value): (self.run/name).write_text(json.dumps(value),encoding=\'utf-8\')\n def evidence(self,identifier,owners):\n  item={\'id\':identifier,\'test_ids\':owners,\'kind\':\'test_metadata\'}\n  item[\'content_hash\']={\'algorithm\':\'sha256\',\'scope\':\'Canonical JSON excluding content_hash\',\'value\':_digest(item)}\n  self.save(\'evidence/\'+identifier+\'.json\',item)\n def submit(self,payload=None,**kwargs):\n  return save_review(self.run,\'test-one\',deepcopy(PAYLOAD if payload is None else payload),provider=\'ollama\',model=\'qwen3:8b\',**kwargs)\n def test_pending_init_is_idempotent_and_no_network(self):\n  with patch(\'httpx.AsyncClient\',side_effect=AssertionError(\'network\')):\n   state=initialize(self.run)\n   self.assertEqual(state[\'status\'],\'pending\');self.assertEqual(state[\'reviews\'],[])\n   before=(self.run/REVIEW_PATH).read_bytes();initialize(self.run)\n   self.assertEqual((self.run/REVIEW_PATH).read_bytes(),before)\n def test_valid_review_stays_separate_and_is_idempotent_by_test(self):\n  before={p:p.read_bytes() for p in self.run.rglob(\'*.json\')}\n  state=self.submit();self.assertEqual(state[\'status\'],\'complete\')\n  self.assertEqual(state[\'reviews\'][0][\'scanner_status\'],\'Potential\')\n  self.assertTrue(state[\'reviews\'][0][\'review_required\'])\n  self.submit();self.assertEqual(len(load_reviews(self.run)[\'reviews\']),1)\n  for p,data in before.items():self.assertEqual(p.read_bytes(),data)\n def test_extra_status_severity_commands_and_bad_text_rejected(self):\n  for patch_value in ({\'status\':\'Confirmed\'},{\'severity\':\'Critical\'},{\'command\':\'curl target\'},\n                      {\'explanation\':\'\'},{\'explanation\':\'x\'*2201},{\'uncertainty\':\'\\u09ac\\u09be\\u0982\\u09b2\\u09be\'},\n                      {\'assessment\':\'confirmed\'}):\n   with self.assertRaises(ReviewError):self.submit(dict(PAYLOAD,**patch_value))\n  self.assertFalse((self.run/REVIEW_PATH).exists())\n def test_missing_duplicate_unknown_and_path_refs_rejected(self):\n  for refs in ([],[\'ev-one\',\'ev-one\'],[\'ev-missing\'],[\'../../scan.json\']):\n   with self.assertRaises(ReviewError):self.submit(dict(PAYLOAD,evidence_refs=refs))\n def test_evidence_from_another_test_rejected(self):\n  self.tests.append(dict(self.test,id=\'test-two\',evidence_refs=[\'ev-two\']))\n  self.save(\'results/tests.json\',self.tests);self.evidence(\'ev-two\',[\'test-two\'])\n  with self.assertRaisesRegex(ReviewError,\'belong\'):self.submit(dict(PAYLOAD,evidence_refs=[\'ev-two\']))\n def test_missing_backlink_rejected(self):\n  self.evidence(\'ev-one\',[\'different-test\'])\n  with self.assertRaisesRegex(ReviewError,\'backlink\'):initialize(self.run)\n def test_tampered_evidence_hash_rejected(self):\n  path=self.run/\'evidence/ev-one.json\';item=json.loads(path.read_text());item[\'kind\']=\'changed\'\n  self.save(\'evidence/ev-one.json\',item)\n  with self.assertRaisesRegex(ReviewError,\'hash\'):initialize(self.run)\n def test_source_change_rejects_stale_store_without_overwrite(self):\n  self.submit();before=(self.run/REVIEW_PATH).read_bytes()\n  self.test[\'reason\']=\'Changed observation\';self.save(\'results/tests.json\',self.tests)\n  for action in (lambda:initialize(self.run),lambda:load_reviews(self.run),lambda:self.submit()):\n   with self.assertRaisesRegex(ReviewError,\'stale\'):action()\n  self.assertEqual((self.run/REVIEW_PATH).read_bytes(),before)\n def test_incorrect_rule_or_status_in_saved_store_rejected(self):\n  self.submit();state=json.loads((self.run/REVIEW_PATH).read_text())\n  for field,value in ((\'rule_id\',\'CHK07\'),(\'scanner_status\',\'Confirmed\')):\n   changed=deepcopy(state);changed[\'reviews\'][0][field]=value;self.save(REVIEW_PATH,changed)\n   with self.assertRaises(ReviewError):load_reviews(self.run)\n def test_wrong_followup_and_provider_rejected(self):\n  with self.assertRaises(ReviewError):self.submit(dict(PAYLOAD,suggested_verification=\'review_reflection_context\'))\n  with self.assertRaises(ReviewError):save_review(self.run,\'test-one\',PAYLOAD,provider=\'unknown\',model=\'demo\')\n def test_not_tested_and_unsupported_are_not_applicable(self):\n  for updates in ({\'status\':\'Not Tested\'},{\'rule_id\':\'CHK03\'}):\n   self.save(\'results/tests.json\',[dict(self.test,**updates)])\n   state=initialize(self.run);self.assertEqual(state[\'status\'],\'not_applicable\')\n   with self.assertRaises(ReviewError):self.submit()\n   (self.run/REVIEW_PATH).unlink()\n def test_duplicate_source_and_review_ids_rejected(self):\n  self.save(\'results/tests.json\',[self.test,self.test])\n  with self.assertRaises(ReviewError):initialize(self.run)\n  self.save(\'results/tests.json\',[self.test]);self.submit()\n  state=json.loads((self.run/REVIEW_PATH).read_text());state[\'reviews\']*=2;self.save(REVIEW_PATH,state)\n  with self.assertRaises(ReviewError):load_reviews(self.run)\n def test_partial_and_false_complete_rejected(self):\n  self.tests.append(dict(self.test,id=\'test-two\',evidence_refs=[\'ev-two\']))\n  self.save(\'results/tests.json\',self.tests);self.evidence(\'ev-two\',[\'test-two\'])\n  state=self.submit();self.assertEqual(state[\'status\'],\'partial\')\n  state[\'status\']=\'complete\';self.save(REVIEW_PATH,state)\n  with self.assertRaises(ReviewError):load_reviews(self.run)\n def test_malformed_store_never_silently_replaced(self):\n  for content in (\'{"schema_version":1,"schema_version":1}\', \'{bad\', \'{"x":NaN}\', \'x\'*(4*1024*1024+1)):\n   (self.run/REVIEW_PATH).write_text(content)\n   with self.assertRaises(ReviewError):initialize(self.run)\n   self.assertEqual((self.run/REVIEW_PATH).read_text(),content)\n def test_lock_and_atomic_write_failure(self):\n  initialize(self.run);before=(self.run/REVIEW_PATH).read_bytes()\n  with lock_run(self.run):\n   with self.assertRaises(ValueError):self.submit()\n  with patch(\'os.replace\',side_effect=OSError(\'simulated failure\')):\n   with self.assertRaises(OSError):self.submit()\n  self.assertEqual((self.run/REVIEW_PATH).read_bytes(),before)\n  self.assertEqual(list((self.run/\'results\').glob(\'.pending-*\')),[])\n def test_symlink_destination_rejected(self):\n  target=Path(self.temp.name)/\'outside.json\';target.write_text(\'untouched\')\n  (self.run/REVIEW_PATH).symlink_to(target)\n  with self.assertRaises(ReviewError):initialize(self.run)\n  self.assertEqual(target.read_text(),\'untouched\')\n def test_evidence_filename_mismatch_rejected(self):\n  (self.run/\'evidence/ev-one.json\').rename(self.run/\'evidence/wrong.json\')\n  with self.assertRaises(ReviewError):initialize(self.run)\n', 'docs/ai-review-foundation.md': '# AI review foundation (schema version 1)\n\nThis step adds strict review schemas, evidence-reference validation and separate\nstorage. It does not call a model, send target requests, run follow-up actions,\nchange scanner verdicts or add review text to HTML reports. Existing automatic\nEnglish report explanations continue to use `results/ai.json` independently.\nThe later AI-review integration will call the APIs documented below.\n\n## Initialize and validate\n\nUse a saved run with valid scan, tests, findings and evidence files:\n\n```bash\n.venv/bin/python -m auditor.review.store --run runs/scan-YOUR_RUN_ID --init\n.venv/bin/python -m auditor.review.store --run runs/scan-YOUR_RUN_ID --validate\n```\n\nThe commands use no network; Ollama and the SSH tunnel are not needed.\n`--init` creates `results/ai_review.json` with an empty reviews list. It never\nfabricates AI output. Existing valid reviews are preserved. No default scan or\nreport command automatically creates this new store in this foundation release.\n\nStatus meanings:\n\n- `pending`: eligible tests exist; no reviews saved yet.\n- `partial`: some eligible tests have stored reviews.\n- `complete`: every eligible test has a stored, structurally valid review.\n- `not_applicable`: no eligible tests exist.\n\nComplete means review storage is complete, not that the site is secure or that\nAI statements were verified. Eligibility currently means CHK05, CHK07 or CHK08,\na status other than Not Tested, and at least one evidence reference. Even a\nNo Issue Observed test may be reviewed for scope and limitations.\n\n## Model payload schema\n\nBundled schema: `auditor/reporting/schemas/ai_review.json`, definition `payload`.\nA future model will produce only this object (example, not an actual AI review):\n\n```json\n{\n  "assessment": "needs_human_review",\n  "explanation": "A server error alone does not demonstrate SQL injection.",\n  "uncertainty": "Only one malformed value was tested.",\n  "evidence_refs": ["ev-EXAMPLE"],\n  "suggested_verification": "review_input_handling"\n}\n```\n\nAssessment enum: `consistent_with_observation`, `possible_false_positive`,\n`insufficient_context`, `needs_human_review`. These are AI-review labels, not\nscanner verdicts. Free-form `status`, `severity`, `command`, URL or other extra\nfields are rejected. Each prose field is 1–2200 characters. Bengali script is\nrejected; this is not a comprehensive language detector. English prompts and\nhuman review remain necessary. Text is untrusted data, never executable content.\n\nAllowed suggestions are `none` and the matching manual-review action:\n\n| Rule | Suggestion ID |\n| --- | --- |\n| CHK05 | `review_error_context` |\n| CHK07 | `review_reflection_context` |\n| CHK08 | `review_input_handling` |\n\nThese names do not refer to executable verification modules. No action dispatcher\nexists in this step. Future consumers must escape prose before displaying HTML.\n\n## Evidence and source validation\n\nValidation checks:\n\n1. Source JSON satisfies existing report schemas; duplicate test/evidence IDs fail.\n2. Each evidence filename matches its record ID and its canonical SHA-256 is valid.\n3. Every cited ID exists and appears in the reviewed test\'s evidence references.\n4. That evidence links back to the same test through test_id or test_ids.\n5. Review metadata matches the actual test\'s rule and scanner status.\n6. References are non-empty and unique; no duplicate reviews for a test.\n7. The store matches its run ID and source snapshot hash.\n8. Completion status matches the actual number of reviewed eligible tests.\n\nSource snapshot covers parsed scan.json, tests.json, findings.json and evidence\nrecords. Changing those inputs invalidates old review stores, including a scan\nresume that changes saved results. Formatting-only JSON changes do not invalidate\nit. Missing/malformed/stale stores are never silently replaced. Archive a stale\nstore explicitly before initializing one for changed results. Initialize reviews\non a finished run when possible.\n\nHash checks detect inconsistent content, not cryptographic authenticity. A local\nactor able to edit both data and hashes can forge records. Reference validation\ndoes not prove that an AI explanation is supported semantically by the evidence.\nNo reviewer label certifies a vulnerability. Metadata is not proof of a model call.\n\n## Integration API (for the next step)\n\n```python\nfrom auditor.review.store import initialize, load_reviews, save_review\n\nstate = initialize(run_directory)\n# payload will come from a future provider call, not from this storage module.\nstate = save_review(\n    run_directory,\n    selected_test_id,\n    validated_model_payload,\n    provider="ollama",\n    model="qwen3:8b",\n)\nstate = load_reviews(run_directory)\n```\n\nThe caller binds the test ID and provider/model from trusted invocation context.\nThe model cannot set those envelope fields. The store derives scanner_status,\nrule_id, timestamp and review_required=true. Saving again for one test replaces\nthat review without creating duplicates. Other reviews are retained.\n\nThe same per-run lock used by scanning protects review reads and writes. Stores\nare bounded to 4 MiB and 1000 entries; writes use atomic replacement. Invalid\nupdates and failed writes preserve the previous store. The source files,\nscanner findings, report AI cache and existing HTML report are not modified.\nNo API key is required or accepted by these storage functions.\n\n## Installation and testing\n\nInstall after the check-selection update. Finish paused scans before upgrading:\nnew Python modules change the code fingerprint. Old saved result files can\nstill be initialized and validated without resuming their scan checkpoints.\n\n```bash\n.venv/bin/python install_ai_review_foundation.py\n.venv/bin/python -m unittest discover -s tests -v\n```\n\nThe installer backs up changed files under `.ai-review-backups` and performs no\nscan, network request or Git operation. It does not initialize run data for you.\nThe schema is included by the existing package-data rule in wheel builds.\n\nTests cover valid storage, source preservation, unknown/unrelated evidence,\nbacklink and hash mismatch, extra fields, bounded prose, duplicate IDs, stale\nsource, partial/completion accounting, corrupt JSON, lock contention, symlink\nrejection and atomic-write failure. They do not establish model quality.\n', 'docs/usage-v0.1.md': "# OWASP Web Auditor 0.1.0\n\nA development CLI for bounded web configuration observations, selected input\nchecks, evidence records and self-contained HTML reports. It is not an exhaustive\nOWASP Top 10 assessment or an exploitation framework. Potential findings need\ncontextual confirmation. Zero findings does not establish that a target is secure.\n\n## Install on Kali/Linux\n\nPython 3.11 or newer is required. Development tests have run on Python 3.12;\nuser-side tests have run on Kali Python 3.13. Resume uses POSIX file locking;\nnative Windows is not supported. Run the tool inside Kali or another Linux environment.\n\nFrom the project directory:\n\n```bash\npython3 -m venv .venv\n.venv/bin/python -m pip install -e .\n.venv/bin/owasp-auditor --version\n.venv/bin/owasp-auditor --help\n.venv/bin/python -m unittest discover -s tests -v\n```\n\nFor an existing virtual environment, reuse it and run only the install command.\n`pip install -r requirements.txt` is an alternative to `pip install -e .`.\nNo `sudo pip` is needed. Installation needs access to the Python package index.\nThe supported console commands and `python -m auditor` use the same dispatcher.\nActivate the virtual environment (`source .venv/bin/activate`) to use command\nnames without their `.venv/bin/` prefix.\n\n## Basic scan\n\nUse a target you own or are authorized to assess. Start your local demo server\nseparately; the auditor does not start target applications.\n\n```bash\n.venv/bin/owasp-auditor --url http://127.0.0.1:8001/discovery.html\n# Equivalent:\n.venv/bin/python -m auditor --url http://127.0.0.1:8001/discovery.html\n```\n\nChoose a configuration/output directory explicitly when needed:\n\n```bash\n.venv/bin/owasp-auditor --url http://127.0.0.1:8001/ \\\n  --profile config/public.json --output runs\n```\n\nIf `--profile` is omitted, an existing `config/public.json` in the current\nworking directory takes precedence; otherwise the installed public profile is\nused. An invalid local/explicit profile fails rather than silently falling back.\nThe bundled profile allows 50 attempted requests, 10 seconds per request,\n120 seconds active scan time, 1 MiB per response, depth 2 and 5 redirects.\nTLS verification is required. All requests share the budget.\nOutputs default to `runs/` relative to the current working directory.\n\nThe top-level target must not contain credentials or query parameters. Explicit\nparameter probes generate their own values. Fragments are discarded.\n\n## Explicit parameter checks\n\nSelect only read-only inputs appropriate for the stated test:\n\n```bash\n.venv/bin/owasp-auditor --url http://127.0.0.1:8002/search --reflection-param q\n.venv/bin/owasp-auditor --url http://127.0.0.1:8003/item --exception-param id\n```\n\nReflection checks use a harmless marker and do not demonstrate XSS. Exceptional\ninput checks compare numeric baseline `1` to one malformed value; they do not\nestablish SQL injection. Probe redirects are not followed. Forms are never submitted.\n\n## Pause and resume\n\nPress Ctrl+C once and wait for graceful checkpoint/output saving. Resume using\nthe actual run directory printed by the tool:\n\n```bash\n.venv/bin/owasp-auditor --resume runs/scan-YOUR_RUN_ID\n# Equivalent:\n.venv/bin/python -m auditor --resume runs/scan-YOUR_RUN_ID\n```\n\nUse `--resume` without a new target, profile, output or probe option.\nAI provider options may be supplied for the report stage.\nThe original settings and request/active-time budgets are preserved. Paused\nwall-clock time is excluded. Completed tasks are kept; an interrupted task or\nbaseline/probe pair may repeat and consumes the remaining request budget.\nResults can span sessions and target content can change between them.\nCompleted runs do not send requests again. Exhausted budgets are not reset.\nRuns created before checkpoint support cannot be resumed. Force-kill, power\nloss and repeated Ctrl+C are not equivalent to graceful cancellation.\nFinish pending scans before code or environment upgrades; changed fingerprints\nare rejected. Never run two processes against the same run directory.\n\n## Reports and validation (no target requests)\n\nReports include automatic English AI explanations using local Ollama or an\nHTTPS Chat Completions-compatible API. See `docs/automatic-ai.md` for command\noptions, API-key setup, retries and data handling. The report command contacts\nthe configured AI provider when needed; it does not contact the target.\n\nReplace `scan-YOUR_RUN_ID` with the actual run name:\n\n```bash\n.venv/bin/owasp-auditor-validate --run runs/scan-YOUR_RUN_ID\n.venv/bin/owasp-auditor-integrity --run runs/scan-YOUR_RUN_ID\n.venv/bin/owasp-auditor-report --run runs/scan-YOUR_RUN_ID\nfirefox runs/scan-YOUR_RUN_ID/reports/report.html\n```\n\nModule equivalents:\n\n```bash\n.venv/bin/python -m auditor.reporting.validation --run runs/scan-YOUR_RUN_ID\n.venv/bin/python -m auditor.verification.integrity --run runs/scan-YOUR_RUN_ID\n.venv/bin/python -m auditor.reporting.html_report --run runs/scan-YOUR_RUN_ID\n```\n\nSchema validation covers report input structure/types, not every output file.\nThe integrity audit checks saved references, hashes, request accounting and\nknown fixture markers; it is not authentication or a full secret scan.\nSee `docs/reporting.md` for details. The HTML report loads no external assets.\nMissing session history in pre-resume runs is expected.\n\n## Implemented checks\n\n| Rule | Observation | Main limitation |\n| --- | --- | --- |\n| CHK01 | HTTP root HTTPS redirect handling | Root URL only; no complete TLS review |\n| CHK02 | Framing policy indicators | Policy presence does not establish effectiveness |\n| CHK03 | Content-Type and nosniff | MIME/browser behavior not verified |\n| CHK04 | Selected cookie attributes | Cookie purpose and authentication impact unknown |\n| CHK05 | Python/PHP error structures | Documentation may match; other formats untested |\n| CHK06 | Common English directory listings | No file contents requested or intent assessed |\n| CHK07 | Harmless query reflection | Reflection is not XSS |\n| CHK08 | Numeric input error handling | One baseline/value; not injection confirmation |\n\nThe bounded crawler follows eligible query-free .html/.htm links, honors scope\nand depth, skips duplicates, inventories forms without submitting them and does\nnot execute JavaScript. Recognized directory entries are not expanded.\nCoverage lists ten OWASP categories, but only selected aspects of A02/A04/A05/A10\nhave implemented checks. Other categories require additional testing/evidence.\n\n## Result interpretation and retention\n\n- `Confirmed`: a supported check established its stated condition; no general security guarantee.\n- `Potential`: an observation requires contextual confirmation.\n- `Inconclusive`: the check cannot support a reliable conclusion.\n- `No Issue Observed`: no issue observed only for this particular executed check.\n- `Not Tested`: prerequisites were unmet or the check was not selected.\n\n`finished` describes run processing, not full category coverage. Review skipped\nchecks, limitations, stop reasons and missing results before interpreting counts.\nQuery/form values and raw cookie values are omitted by the implemented paths.\nURL paths and input names are retained. Do not assume every possible secret is\nredacted. Keep real scan results and checkpoints out of public repositories.\n\nEach run can contain scan.json, checkpoint.json, request_ledger.json,\nresults/{tests,findings,findings_raw,plan,coverage,integrity}.json,\ndiscovery/endpoints.json, evidence/*.json and reports/report.html.\n\n## Troubleshooting\n\n- `Address already in use`: the demo port is occupied. Use the existing intended server or select another port and update the target URL.\n- `network_error`: verify the server is still running and the URL/port is correct.\n- `response_not_declared_html`: discovery intentionally skipped non-HTML content.\n- `Not Tested`: read the rule's reason; it is not automatically a tool error.\n- `ModuleNotFoundError`: use the project's venv and rerun `pip install -e .`.\n- Schema failure: inspect the identified file/field. Do not edit a result just to force PASS.\n- Changed checkpoint fingerprint: restore the original code/environment or start a new run.\n- `Executing <Task ...> took ...`: unittest asyncio timing diagnostics can appear even when all tests pass.\n\nThe legacy `auditor.probe` and `auditor.run_check` development modules are not\nthe supported scan entry point. Prefer `owasp-auditor` / `python -m auditor`.\n\n## Build a wheel\n\n```bash\n.venv/bin/python -m pip wheel --no-deps . --wheel-dir dist\n```\n\nThe wheel includes the default profile, report template and JSON schemas.\nDependencies still need to be installed by pip when installing the wheel.\nNo repository URL or license grant is invented by this package. Publication,\nlicense selection and the final GitHub push remain separate release work.\n\n## Select checks and control discovery\n\nUse `--list-checks` without a URL to list supported rules. Use\n`--checks CHK02,CHK03 --no-crawl` to inspect only the supplied page for those\nchecks. AI remains automatic. See `docs/check-selection.md` for prerequisites,\nrequest behavior and resume rules.\n\n## AI review foundation\n\nIndependent review storage and evidence validation are available via\n`python -m auditor.review.store --run runs/scan-YOUR_RUN_ID --init` and\n`--validate`. This foundation performs no AI generation or target requests and\ndoes not change scanner verdicts. See `docs/ai-review-foundation.md`.\n"}

